define(["core/str","core_user/repository","core/config"],function(str,Repository,Config){function syncPreference(key,value){if(!Config.userId||Config.userId==="0"||Config.isguest){return}const encodedValue=typeof value==="boolean"?value?"true":"false":value;const url=Config.wwwroot+"/local/suap/api/index.php?sync_user_preference"+"&category=accessibility"+"&key="+key+"&value="+encodeURIComponent(encodedValue)+"&sesskey="+Config.sesskey;fetch(url,{method:"GET",credentials:"same-origin"}).then(resp=>resp.json()).catch(()=>{})}let colorPreferences={color_mode:"default",color_mode_options:["default","high_contrast","low_contrast","colorblind","grayscale"]};let preferences={zoom_level:100,zoom_options:[100,120,130,150,160]};function activeAccessibility(){let checkboxes=document.querySelectorAll('.custom-checkbox-access input[type="checkbox"]');checkboxes.forEach(checkbox=>{checkbox.addEventListener("change",event=>{let target=event.target;const checked=target.checked;const className=`accessibility_${target.id}`;const prefName=`theme_suap_accessibility_${target.id}`;if(checked){document.body.classList.add(className)}else{document.body.classList.remove(className)}if(Config.userId&&Config.userId!=="0"&&!Config.isguest){Repository.setUserPreference(prefName,checked).catch(()=>{})}syncPreference(target.id,checked)})})}function renderZoom(){const container=document.getElementById("selector-cycle-access");const zoomValue=document.getElementById("zoom-value");const indicators=document.getElementById("cycle-indicators");if(container){if(preferences.zoom_level>100){container.classList.add("active")}else{container.classList.remove("active")}}if(zoomValue){zoomValue.textContent=preferences.zoom_level+"%"}if(indicators){indicators.innerHTML="";preferences.zoom_options.filter(level=>level>100).forEach(level=>{const span=document.createElement("span");span.classList.add("cycle-indicator");if(level<=preferences.zoom_level){span.classList.add("active")}indicators.appendChild(span)})}}function renderColorMode(){const colorContainer=document.getElementById("selector-cycle-color");const colorLabel=document.getElementById("color-mode-label");const colorIndicators=document.getElementById("color-indicators");const mode=colorPreferences.color_mode;const labels={default:"Padrão",high_contrast:"Alto contraste",low_contrast:"Contraste reduzido",colorblind:"Amigável a daltônicos",grayscale:"Escala de cinza"};if(colorLabel){colorLabel.textContent=labels[mode]||"Padrão"}if(colorIndicators){colorIndicators.innerHTML="";colorPreferences.color_mode_options.filter(m=>m!=="default").forEach(m=>{const span=document.createElement("span");span.classList.add("cycle-indicator");if(m===mode){span.classList.add("active")}colorIndicators.appendChild(span)})}if(colorContainer){if(mode!=="default"){colorContainer.classList.add("active")}else{colorContainer.classList.remove("active")}}}function cycleAccessibility(){const currentIndex=preferences.zoom_options.indexOf(preferences.zoom_level);const nextIndex=(currentIndex+1)%preferences.zoom_options.length;preferences.zoom_level=preferences.zoom_options[nextIndex];if(Config.userId&&Config.userId!=="0"&&!Config.isguest){Repository.setUserPreference("theme_suap_accessibility_zoom_level",preferences.zoom_level).catch(()=>{})}syncPreference("zoom_level",preferences.zoom_level);document.body.setAttribute("data-zoom",preferences.zoom_level);renderZoom()}function cycleColorMode(){const modes=colorPreferences.color_mode_options;const currentIndex=modes.indexOf(colorPreferences.color_mode);const nextIndex=(currentIndex+1)%modes.length;colorPreferences.color_mode=modes[nextIndex];if(Config.userId&&Config.userId!=="0"&&!Config.isguest){Repository.setUserPreference("theme_suap_accessibility_color_mode",colorPreferences.color_mode).catch(()=>{})}syncPreference("color_mode",colorPreferences.color_mode);const allModes=colorPreferences.color_mode_options;allModes.forEach(m=>{document.body.classList.remove(`accessibility_color_mode_${m}`)});document.body.classList.add(`accessibility_color_mode_${colorPreferences.color_mode}`);renderColorMode()}function syncInputWithBody(){document.querySelectorAll('.custom-checkbox-access input[type="checkbox"]').forEach(input=>{input.checked=false});document.body.classList.forEach(cls=>{if(cls.startsWith("accessibility_")){const id=cls.replace("accessibility_","");const checkbox=document.getElementById(id);if(checkbox&&checkbox.type==="checkbox"){checkbox.checked=true}}})}function setupAccessibility(){const button=document.getElementById("cycle-toggle");const colorButton=document.getElementById("color-mode-toggle");if(button){button.addEventListener("click",cycleAccessibility)}if(colorButton){colorButton.addEventListener("click",cycleColorMode)}if(Config.userId&&Config.userId!=="0"&&!Config.isguest){Repository.getUserPreference("theme_suap_accessibility_zoom_level").then(value=>{if(value){preferences.zoom_level=parseInt(value)}renderZoom()}).catch(()=>{renderZoom()});Repository.getUserPreference("theme_suap_accessibility_color_mode").then(value=>{if(value){colorPreferences.color_mode=value}renderColorMode()}).catch(()=>{renderColorMode()})}else{renderZoom();renderColorMode()}}return{init:()=>{syncInputWithBody();activeAccessibility();setupAccessibility()}}});